/* Foto To Link workspace — extracted from index.html v3. Classic script; keep execution order. */

/* ===== original script 22: inline-22 ===== */
(function(){
  var PIX_B64 = "";
  var ov=null,back=null,blobUrl=null;

  function buildOnce(){
    if(ov) return;
    var bin=atob(PIX_B64),bytes=new Uint8Array(bin.length);
    for(var i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
    blobUrl=URL.createObjectURL(new Blob([bytes],{type:"text/html"}));
    ov=document.createElement("div"); ov.id="pixOverlay";
    ov.style.display="none";
    /* top bar */
    var bar=document.createElement("div"); bar.id="pixTopBar";
    var btn=document.createElement("div"); btn.id="pixTopBack";
    btn.innerHTML='<i class="fas fa-chevron-left"></i> All Tools Nexora';
    btn.addEventListener("click",closePix);
    var ttl=document.createElement("span"); ttl.id="pixTopTitle";
    ttl.textContent="Foto To Link";
    bar.appendChild(btn); bar.appendChild(ttl);
    ov.appendChild(bar);
    /* iframe */
    var fr=document.createElement("iframe");
    fr.setAttribute("sandbox","allow-scripts allow-same-origin allow-forms allow-popups allow-modals allow-downloads");
    fr.src=blobUrl;
    ov.appendChild(fr);
    /* desktop side tab */
    back=document.createElement("div"); back.id="pixBack";
    back.innerHTML='<span class="arr">\u25B2</span>ALL TOOLS';
    back.title="Kembali ke All Tools";
    back.addEventListener("click",closePix);
    document.body.appendChild(ov);
    document.body.appendChild(back);
  }

  window.openPix=function(){
    buildOnce();
    ov.style.display="flex"; back.style.display="flex";
    requestAnimationFrame(function(){ ov.classList.add("on"); });
  };

  function closePix(){
    if(!ov) return;
    ov.classList.remove("on");
    setTimeout(function(){ ov.style.display="none"; back.style.display="none"; },300);
  }

  document.addEventListener("keydown",function(e){
    if(e.key==="Escape" && ov && ov.classList.contains("on")) closePix();
  });

  function patchFoto(){
    document.querySelectorAll(".tools-card h4").forEach(function(h){
      if(h.textContent.trim()!=="Foto To Link") return;
      var card=h.closest(".tools-card");
      if(!card) return;
      card.removeAttribute("onclick");
      card.onclick=window.openPix;
    });
  }
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",patchFoto);
  else patchFoto();
})();
